    public enum UILoginState
    {
        QuickStart,
        Login,
        CreateRole,
        ChangeName,
        Reg,
        GameDispatch,
        Hide,
    }
    
    public class ShowUISDKLoginParam
    {
        public UILoginState InitState = UILoginState.Login; 
    }

    public class UISDKLogin : UIPage, IPointerClickHandler
    {
        public GameObject LoginRoot;
        public GameObject RegRoot;
        public UISelectHeadIconAndName CreateRoleRoot;
        public UIGameDispatch GameDispatch;
        public UILeadBoard LeadBoard;
        public UINoticePanel NoticePanel;

        //ugui输入框
        public TMP_InputField UserNameInput;
        public TMP_InputField PasswordInput;

        public TMP_InputField RegAccountInput;
        public TMP_InputField RegPasswordInput;
        public TMP_InputField RegRealNameInput;
        public TMP_InputField RegRealIdCardInput;

        public Button AgeNotifyBtn;
        public Button AdultNotifyBtn;
        public Button BackToStartBtn;
        public Button BackToLoginBtn;

        public Button StartRegBtn;
        public Button RegToServerBtn;

        public Button NativeLoginBtn;
        public Button QuickLoginBtn;

        public Toggle ToggleLogin;
        public Toggle ToggleReg;
        public TextMeshProUGUI UserAndPriviteLogin;
        public TextMeshProUGUI UserAndPriviteReg;

        public GameObject startPanel;
        public GameObject policy;


        private UILoginState curState;
        private bool isDoingCoroutine = false;
        private bool antiAddictionShown = false;
        
        private GameObject bgColor;
        private GameObject bgColor_login;

        public override void Initialise()
        {
            StartRegBtn.onClick.AddListener(this.StartReg);
            BackToLoginBtn.onClick.AddListener(this.StartLogin);
            RegToServerBtn.onClick.AddListener(this.RegToServer);
            NativeLoginBtn.onClick.AddListener(this.LoginToServer);
            BackToStartBtn.onClick.AddListener(this.BackToStart);
            QuickLoginBtn.onClick.AddListener(this.QuickLoginToServer);
            AgeNotifyBtn.onClick.AddListener(this.AgeNotifies);
            AdultNotifyBtn.onClick.AddListener(this.AdultNotifies);
            

            GameDispatch.ClickGoLevelBtn = this.GoToLevel;
            GameDispatch.ClickLeaderBoardBtn = this.OpenLeaderBoard;
            GameDispatch.ClickLogoutBtn = this.StartLogin;
            GameDispatch.ClickChangeNameBtn = this.ChangeHeadIconAndName;

            LeadBoard.OnClickCloseBtn = this.ToGameDispatch;

            CreateRoleRoot.Init();
            
            bgColor = transform.Find("bgColor")?.gameObject;
            bgColor_login = transform.Find("bgColor_login")?.gameObject;

            // Backgrounds are decorative; keep them from stealing button clicks.
            var bgImage = bgColor != null ? bgColor.GetComponent<Image>() : null;
            if (bgImage != null) bgImage.raycastTarget = false;
            var bgLoginImage = bgColor_login != null ? bgColor_login.GetComponent<Image>() : null;
            if (bgLoginImage != null) bgLoginImage.raycastTarget = false;

            // Do not SetState here — PlayShowAnimation decides the visible page
            // (avoids forcing QuickStart/Logout before opening GameDispatch).
        }

        public override void PlayShowAnimation(object param = null)
        {
            if (param is ShowUISDKLoginParam openParam)
            {
                SetState(openParam.InitState);
            }
            else
            {
                SetState(UILoginState.QuickStart);
            }

            NoticePanel.gameObject.SetActive(false);
            UIController.OnPageOpened(this);
        }

        public override void PlayHideAnimation()
        {
            this.SetState(UILoginState.Hide);
            UIController.OnPageClosed(this);
        }

        private void StartReg()
        {
            this.SetState(UILoginState.Reg);
        }
        

        private void StartQuickLogin()
        {
            this.SetState(UILoginState.QuickStart);
        }

        private void StartLogin()
        {
            this.SetState(UILoginState.Login);
        }

        private void ChangeHeadIconAndName()
        {
            this.SetState(UILoginState.ChangeName);
        }

        private void BackToStart()
        {
            this.SetState(UILoginState.QuickStart);
        }

        private void ToGameDispatch()
        {
            var roleModule = GetModule<RoleModule>();
            if (!roleModule.IsTutorialOver())
            {
                UIController.HidePage<UISDKLogin>();
                UIController.ShowPage<UIStory>();
                return;
            }
            this.SetState(UILoginState.GameDispatch);
        }


        private void ResetShow()
        {
            this.LoginRoot.SetActive(false);
            this.RegRoot.SetActive(false);
            this.CreateRoleRoot.gameObject.SetActive(false);
            this.QuickLoginBtn.gameObject.SetActive(false);
            this.GameDispatch.gameObject.SetActive(false);
            this.LeadBoard.gameObject.SetActive(false);
            this.AgeNotifyBtn.gameObject.SetActive(true);
            if (startPanel != null) startPanel.SetActive(false);
            if (policy != null) policy.SetActive(true);
        }

        private void SetState(UILoginState state)
        {
            curState = state;
            ResetShow();
            
            switch (state)
            {
                case UILoginState.QuickStart:
                    GetModule<RoleModule>().Logout();
                    this.QuickLoginBtn.gameObject.SetActive(true);
                    if (startPanel != null) startPanel.SetActive(true);
                    if (bgColor != null) bgColor.SetActive(false);
                    if (bgColor_login != null) bgColor_login.SetActive(true);
                    break;
                case UILoginState.Login:
                    GetModule<RoleModule>().Logout();
                    this.UserNameInput.text = "";
                    this.PasswordInput.text = "";
                    this.LoginRoot.SetActive(true);
                    if (bgColor != null) bgColor.SetActive(false);
                    if (bgColor_login != null) bgColor_login.SetActive(true);
                    break;
                case UILoginState.Reg:
                    GetModule<RoleModule>().Logout();
                    this.RegAccountInput.text = "";
                    this.RegPasswordInput.text = "";
                    this.RegRealNameInput.text = "";
                    this.RegRealIdCardInput.text = "";
                    this.RegRoot.SetActive(true);
                    if (bgColor != null) bgColor.SetActive(false);
                    if (bgColor_login != null) bgColor_login.SetActive(true);
                    break;
                case UILoginState.ChangeName:
                    this.CreateRoleRoot.gameObject.SetActive(true);
                    var role = this.GetModule<RoleModule>();
                    this.CreateRoleRoot.Show(role.userData.HeadIcon, role.userData.Nickname);
                    this.CreateRoleRoot.OnOver = CreateRoleServer;
                    if (policy != null) policy.SetActive(false);
                    break;
                case UILoginState.CreateRole:
                    this.CreateRoleRoot.gameObject.SetActive(true);
                    this.CreateRoleRoot.Show("", "");
                    this.CreateRoleRoot.OnOver = CreateRoleServer;
                    if (policy != null) policy.SetActive(false);
                    break;
                case UILoginState.GameDispatch:
                    
                    this.AgeNotifyBtn.gameObject.SetActive(false);
                    if (policy != null) policy.SetActive(false);
                    this.GameDispatch.gameObject.SetActive(true);
                    this.GameDispatch.InitData();
                    if (bgColor != null) bgColor.SetActive(true);
                    if (bgColor_login != null) bgColor_login.SetActive(false);
                    break;
                case UILoginState.Hide:
                    break;
            }
            
            LeadBoard.gameObject.SetActive(false);
        }

        private void GoToLevel()
        {
            UIController.HidePage<UISDKLogin>();

            // So LevelScreen BackButton returns to GameDispatch lobby
            PlayerPrefs.SetInt("open_game_dispatch", 1);

            // Same as HomeScreen PlayButton: ScreenTransition → LevelScreen
            AudioController.PlaySound(AudioController.Sounds.buttonSound);
            BubbleShooterKit.Transition.LoadLevel("LevelScreen", 1.0f, UnityEngine.Color.black);
        }
        
        private void OpenLeaderBoard()
        {
            StartCoroutine(StartOnlyTask(OpenLeaderBoardTask()));
        }


      

