        private void QuickLoginToServer()
        {
            StartCoroutine(StartOnlyTask(QuickLoginTask()));
        }
        private void LoginToServer()
        {
            StartCoroutine(StartOnlyTask(LoginTask()));
        }

        private void RegToServer()
        {
            StartCoroutine(StartOnlyTask(RegTask()));
        }

        private void CreateRoleServer(string head, string nick)
        {
            StartCoroutine(StartOnlyTask(CreateRoleTask(head, nick)));
        }
        

        private IEnumerator RegTask()
        {
            if (!this.ToggleReg.isOn)
            {
                FloatingMessage.ShowMessage("请勾选用户协议和隐私政策。");
                yield break;
            }
            
            var req = new MsgCreateReq();
            req.Account = RegAccountInput.text;
            req.Password = MD5Helper.MD5WithSalt(RegPasswordInput.text);

            req.IdName = RegRealNameInput.text;
            req.IdCard = RegRealIdCardInput.text;

            if(string.IsNullOrEmpty(req.Account) || string.IsNullOrEmpty(RegPasswordInput.text))
            {
                this.ShowError(GameErrorCode.UserOrPwdNull);
                yield break;
            }

            if(string.IsNullOrEmpty(req.IdName) || string.IsNullOrEmpty(req.IdCard))
            {
                this.ShowError(GameErrorCode.UserOrPwdNull);
                yield break;
            }
            
            GameErrorCode errCode = IDCardHelper.CheckIDCard(req.IdCard);
            if (errCode != GameErrorCode.Succ)
            {
                this.ShowError(errCode);
                yield break;
            }

            RequestContext ctx = new RequestContext();
            ctx.method = ServerMethod.Create;
            ctx.Req = req;

            yield return ServerHelper.RequestServer<MsgCreateRsp>(ctx);

            if (ctx.ErrCode != (int)GameErrorCode.Succ)
            {
                if (ctx.ErrCode == (int)GameErrorCode.Fail)
                {
                    FloatingMessage.ShowMessage("注册请求失败，请检查网络或稍后重试。");
                }
                else
                {
                    this.ShowError((GameErrorCode)ctx.ErrCode);
                }
                yield break;
            }

            RoleModule roleModule = GetModule<RoleModule>();
            roleModule.OnRegSucc(ctx.Resp as MsgCreateRsp);

            if (roleModule.IsAdult())
            {
                this.SetState(UILoginState.CreateRole);
            }
            else
            {
                antiAddictionShown = false;
                ShowMessage("防沉迷提示", "         您的账号已被纳入防沉迷系统。根据国家新闻出版署《关于防止未成年人沉迷网络游戏的通知》与《关于进一步严格管理 切实防止未成年人沉迷网络游戏的通知》，您可在周五、周六、周日和法定节假日的20:00-21:00登入游戏。其他时间段，本游戏无法为未成年人用户提供游戏服务。", () =>
                {
                    FloatingMessage.ShowMessage("注册成功，请使用账号登录。");
                    this.SetState(UILoginState.Login);
                });
            }
        }
       
        private IEnumerator CreateRoleTask(string head, string nick)
        {
            var req = new MsgCreateRoleReq();
            req.HeadIcon = head;
            req.NickName = nick;
            req.UserId = GetModule<RoleModule>().userData.UserId;
            req.Token = GetModule<RoleModule>().userData.token;

            RequestContext ctx = new RequestContext();
            ctx.method = ServerMethod.CreateRole;
            ctx.Req = req;

            yield return ServerHelper.RequestServer<MsgCreateRoleRsp>(ctx);

            if (ctx.ErrCode != (int)GameErrorCode.Succ)
            {
                this.ShowError((GameErrorCode)ctx.ErrCode);
                yield break;
            }

            RoleModule roleModule = GetModule<RoleModule>();
            roleModule.OnCreateRoleSucc(req);

            if (curState == UILoginState.ChangeName)
            {
                ToGameDispatch();
            }
            else if (antiAddictionShown)
            {
                antiAddictionShown = false;
                roleModule.RecordLogin();
                ToGameDispatch();
            }
            else
            {
                HandleLoginCompletedByAntiAddiction();
            }
        }


        private IEnumerator OpenLeaderBoardTask()
        {
            AsyncRes res = new AsyncRes();
            yield return GetModule<RankModule>().LoadRandData(res);
            if (res.Code != (int)GameErrorCode.Succ)
            {
                this.ShowError((GameErrorCode)res.Code);
                yield break;
            }
            GameDispatch.gameObject.SetActive(false);
            LeadBoard.gameObject.SetActive(true);
            LeadBoard.InitData();
        }

        private void GotoGame()
        {
            UIController.HidePage<UISDKLogin>();
            if (!GetModule<RoleModule>().IsTutorialOver())
            {
                UIController.ShowPage<UIStory>();
            }
            else
            {
                UIController.ShowPage<UIMainMenu>();
            }
        }

        private IEnumerator StartOnlyTask(IEnumerator co)
        {
            if (isDoingCoroutine)
            {
                yield break;
            }

            isDoingCoroutine = true;

            yield return co;
            isDoingCoroutine = false;
        }

        private IEnumerator QuickLoginTask()
        {
            var roleMdl = GetModule<RoleModule>();
            roleMdl.ReadLocalRoleInfo();
            if (string.IsNullOrEmpty(roleMdl.userData.token) ||
                string.IsNullOrEmpty(roleMdl.userData.Account) ||
                roleMdl.userData.UserId <= 0) 
            {
                this.SetState(UILoginState.Login);
                yield break;
            }
            
            var req = new MsgQuickLoginReq();
            req.Account = roleMdl.userData.Account;
            req.UserId  = roleMdl.userData.UserId;
            req.Token   = roleMdl.userData.token;

            RequestContext ctx = new RequestContext();
            ctx.method = ServerMethod.QuickLogin;
            ctx.Req = req;
            
            yield return ServerHelper.RequestServer<MsgQuickLoginRsp>(ctx);
            if (ctx.ErrCode != (int)GameErrorCode.Succ)
            {
                if (ctx.ErrCode == (int)GameErrorCode.AgeCannotLoginNow || ctx.ErrCode == (int)GameErrorCode.AgeDayDuringMoreThanOneHour)
                {
                    ShowMessage("防沉迷提示", GetAntiAddictionLoginContent(ctx.ErrAge, false), () => { StartLogin(); });
                }
                else
                {
                    this.ShowError((GameErrorCode)ctx.ErrCode);
                }
                this.SetState(UILoginState.Login);
                yield break;
            }
            
            roleMdl.OnQuickLoginSucc(ctx.Resp as MsgQuickLoginRsp);

            HandleLoginCompletedByAntiAddiction();
        }


        private IEnumerator LoginTask()
        {
            if (!this.ToggleLogin.isOn)
            {
                FloatingMessage.ShowMessage("请勾选用户协议和隐私政策。");
                yield break;
            }

            MsgLoginReq req = new MsgLoginReq();
            req.Account = UserNameInput.text;
            req.Password = MD5Helper.MD5WithSalt(PasswordInput.text);

            RequestContext ctx = new RequestContext();
            ctx.method = ServerMethod.Login;
            ctx.Req = req;

            yield return ServerHelper.RequestServer<MsgLoginRsp>(ctx);
            if (ctx.ErrCode != (int)GameErrorCode.Succ)
            {
                if (ctx.ErrCode == (int)GameErrorCode.AgeCannotLoginNow || ctx.ErrCode == (int)GameErrorCode.AgeDayDuringMoreThanOneHour)
                {
                    ShowMessage("防沉迷提示", GetAntiAddictionLoginContent(ctx.ErrAge, false), () => { StartLogin(); });
                }
                else
                {
                    this.ShowError((GameErrorCode)ctx.ErrCode);
                }
                yield break;
            }

            RoleModule roleModule = GetModule<RoleModule>();
            roleModule.OnLoginSucc(ctx.Resp as MsgLoginRsp);

            HandleLoginCompletedByAntiAddiction();
        }

        private void HandleLoginCompletedByAntiAddiction()
        {
            RoleModule roleModule = GetModule<RoleModule>();
            if (roleModule.IsAdult())
            {
                roleModule.RecordLogin();
                if (string.IsNullOrEmpty(roleModule.userData.Nickname) || roleModule.userData.Nickname.Length < 5)
                {
                    this.SetState(UILoginState.CreateRole);
                }
                else
                {
                    ToGameDispatch();
                }
                return;
            }

            bool canPlayNow = roleModule.IsMinorPlayableTimeNow();
            string content = GetAntiAddictionLoginContent(roleModule.Age, canPlayNow);
            NotifyDialog.CloseActive();
            if (!canPlayNow)
            {
                ShowMessage("防沉迷提示", content, () =>
                {
                    StartLogin();
                });
                return;
            }

            antiAddictionShown = true;
            ShowMessage("防沉迷提示", content, () =>
            {
                roleModule.RecordLogin();
                if (string.IsNullOrEmpty(roleModule.userData.Nickname) || roleModule.userData.Nickname.Length < 5)
                {
                    this.SetState(UILoginState.CreateRole);
                }
                else
                {
                    ToGameDispatch();
                }
            });
        }

